begin;
select no_plan();
select ok(not has_table_privilege(r,'private.cocreate_recruitments',p),r||' cannot '||p||' recruitment')
 from unnest(array['anon','authenticated','service_role'])r cross join unnest(array['SELECT','INSERT','UPDATE','DELETE'])p;
select ok(not has_function_privilege('anon','public.join_cocreate_recruitment(uuid,uuid,uuid,uuid,uuid)','execute'),'Anonymous cannot join from a card');
select ok(not has_function_privilege('authenticated',oid,'execute'),proname||' is private') from pg_proc
 where pronamespace='private'::regnamespace and proname like '%cocreate_recruitment%';
update private.cocreate_settings set enabled=true;
insert into private.cocreate_topics(id,label,active) values('cc050000-0000-4000-8000-000000000001','Synthetic recruitment',true);
insert into private.cocreate_hubs(id,topic_id,locality,active) values('cc050000-0000-4000-8000-000000000002','cc050000-0000-4000-8000-000000000001','Synthetic cards',true);
insert into auth.users(id,email) values
 ('cc050000-0000-4000-8000-000000000010','cocreate-card-a@planets.invalid'),
 ('cc050000-0000-4000-8000-000000000011','cocreate-card-b@planets.invalid'),
 ('cc050000-0000-4000-8000-000000000012','cocreate-card-c@planets.invalid');
insert into public.profiles(id,display_name) select id,'Synthetic recruitment person' from auth.users where id::text like 'cc050000%';
insert into private.policy_acceptances(account_id,bundle_version) select id,'POLICY01-2026-10-08-v1' from auth.users where id::text like 'cc050000%';
select set_config('cc.hub','cc050000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claim.sub','cc050000-0000-4000-8000-000000000010',true);
select set_config('cc.ha',public.mutate_cocreate_hub('cc050000-0000-4000-8000-000000000010',gen_random_uuid(),current_setting('cc.hub')::uuid,'join')::text,true);
select set_config('cc.group',public.mutate_cocreate_numbered_group('cc050000-0000-4000-8000-000000000010',gen_random_uuid(),current_setting('cc.hub')::uuid,'create',null,null,2)::text,true);
select set_config('cc.room',current_setting('cc.group')::jsonb->>'room_id',true);
select set_config('cc.ep',current_setting('cc.group')::jsonb->>'episode_id',true);
select set_config('request.jwt.claim.sub','cc050000-0000-4000-8000-000000000011',true);
select set_config('cc.hb',public.mutate_cocreate_hub('cc050000-0000-4000-8000-000000000011',gen_random_uuid(),current_setting('cc.hub')::uuid,'join')::text,true);
select public.send_cocreate_room_message('cc050000-0000-4000-8000-000000000011',gen_random_uuid(),(current_setting('cc.hb')::jsonb->>'room_id')::uuid,(current_setting('cc.hb')::jsonb->>'episode_id')::uuid,'Synthetic human history');
select throws_ok($$select public.mutate_cocreate_recruitment('cc050000-0000-4000-8000-000000000011',gen_random_uuid(),current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,'post',(current_setting('cc.hb')::jsonb->>'episode_id')::uuid)$$,'42501',null,'General membership alone cannot recruit for a child');
select set_config('request.jwt.claim.sub','cc050000-0000-4000-8000-000000000010',true);
select set_config('cc.command',gen_random_uuid()::text,true);
select set_config('cc.post',public.mutate_cocreate_recruitment('cc050000-0000-4000-8000-000000000010',current_setting('cc.command')::uuid,current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,'post',current_setting('cc.ep')::uuid)::text,true);
set constraints all immediate;
set constraints all deferred;
select set_config('cc.card',current_setting('cc.post')::jsonb->>'recruitment_id',true);
select is(public.mutate_cocreate_recruitment('cc050000-0000-4000-8000-000000000010',current_setting('cc.command')::uuid,current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,'post',current_setting('cc.ep')::uuid),current_setting('cc.post')::jsonb,'Exact post retry returns the same immutable card');
select throws_ok($$select public.mutate_cocreate_recruitment('cc050000-0000-4000-8000-000000000010',gen_random_uuid(),current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,'post',current_setting('cc.ep')::uuid)$$,'PT409',null,'A second active card is rejected');
select throws_ok($$update private.cocreate_room_messages set body='Rewritten' where id=(current_setting('cc.post')::jsonb->>'message_id')::uuid$$,'55000',null,'Recruitment never rewrites immutable message history');
select set_config('request.jwt.claim.sub','cc050000-0000-4000-8000-000000000011',true);
select set_config('cc.page',public.get_cocreate_room_page_v2('cc050000-0000-4000-8000-000000000011',(current_setting('cc.hb')::jsonb->>'room_id')::uuid,(current_setting('cc.hb')::jsonb->>'episode_id')::uuid)::text,true);
select is(current_setting('cc.page')::jsonb->'messages'->0->>'kind','recruitment','General v2 renders a distinct structured message');
select is(current_setting('cc.page')::jsonb->'messages'->0->'recruitment'->>'available','true','Card resolves a current free seat');
select is(current_setting('cc.page')::jsonb->'messages'->0->'recruitment'->>'occupied','1','Card includes creator occupancy');
select is(public.get_cocreate_recruitment('cc050000-0000-4000-8000-000000000011',(current_setting('cc.hb')::jsonb->>'room_id')::uuid,(current_setting('cc.hb')::jsonb->>'episode_id')::uuid,current_setting('cc.card')::uuid)->>'recruitment_id',current_setting('cc.card'),'Exact review binds admitted General and card');
select throws_ok($$select public.get_cocreate_recruitment('cc050000-0000-4000-8000-000000000011',current_setting('cc.room')::uuid,(current_setting('cc.hb')::jsonb->>'episode_id')::uuid,current_setting('cc.card')::uuid)$$,'42501',null,'Another room cannot resolve a General card');
select is(private.cocreate_room_unread((select e from private.cocreate_room_episodes e where id=(current_setting('cc.hb')::jsonb->>'episode_id')::uuid)),0::bigint,'Non-human recruitment does not inflate human unread');
select is(jsonb_array_length(public.get_cocreate_room_page('cc050000-0000-4000-8000-000000000011',(current_setting('cc.hb')::jsonb->>'room_id')::uuid,(current_setting('cc.hb')::jsonb->>'episode_id')::uuid)->'messages'),1,'Installed legacy reader remains human-only');
select matches(public.get_cocreate_room_page('cc050000-0000-4000-8000-000000000011',(current_setting('cc.hb')::jsonb->>'room_id')::uuid,(current_setting('cc.hb')::jsonb->>'episode_id')::uuid)->>'read_token','^1[.]','Legacy token binds newest human sequence, not a hidden card');
select set_config('cc.report',(select case_id::text from public.submit_cocreate_room_report('cc050000-0000-4000-8000-000000000011',gen_random_uuid(),(current_setting('cc.post')::jsonb->>'message_id')::uuid,'spam','Synthetic exact card evidence')),true);
select is((select cocreate_evidence->'recruitment'->>'recruitment_id' from private.moderation_cases where id=current_setting('cc.report')::uuid),current_setting('cc.card'),'Report captures only the exact card reference');
select set_config('cc.join',gen_random_uuid()::text,true);
select set_config('cc.b',public.join_cocreate_recruitment('cc050000-0000-4000-8000-000000000011',current_setting('cc.join')::uuid,current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,current_setting('cc.card')::uuid)::text,true);
select is(public.join_cocreate_recruitment('cc050000-0000-4000-8000-000000000011',current_setting('cc.join')::uuid,current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,current_setting('cc.card')::uuid),current_setting('cc.b')::jsonb,'Exact card join retry reuses canonical episode');
select throws_ok($$select public.join_cocreate_recruitment('cc050000-0000-4000-8000-000000000011',current_setting('cc.join')::uuid,current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,gen_random_uuid())$$,'22023',null,'An admission UUID cannot be repurposed to another card');
select is(private.cocreate_recruitment_projection(current_setting('cc.card')::uuid)->>'state','full','Filling the room makes the card non-actionable');
select is((select cocreate_evidence->'recruitment'->>'state' from private.moderation_cases where id=current_setting('cc.report')::uuid),'open','Evidence remains the immutable reported snapshot');
select set_config('request.jwt.claim.sub','cc050000-0000-4000-8000-000000000012',true);
select public.mutate_cocreate_hub('cc050000-0000-4000-8000-000000000012',gen_random_uuid(),current_setting('cc.hub')::uuid,'join');
select throws_ok($$select public.join_cocreate_recruitment('cc050000-0000-4000-8000-000000000012',gen_random_uuid(),current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,current_setting('cc.card')::uuid)$$,'PT409',null,'Stale open card cannot overfill a full room');
select set_config('request.jwt.claim.sub','cc050000-0000-4000-8000-000000000011',true);
select public.mutate_cocreate_numbered_group('cc050000-0000-4000-8000-000000000011',gen_random_uuid(),current_setting('cc.hub')::uuid,'leave',current_setting('cc.room')::uuid,(current_setting('cc.b')::jsonb->>'episode_id')::uuid);
select is(private.cocreate_recruitment_projection(current_setting('cc.card')::uuid)->>'state','open','Leaving reopens the existing card without reposting');
select is((select count(*) from private.cocreate_recruitments where room_id=current_setting('cc.room')::uuid),1::bigint,'Reopening does not post another card');
update private.cocreate_rooms set suppressed=true where id=current_setting('cc.room')::uuid;
select is(private.cocreate_recruitment_projection(current_setting('cc.card')::uuid)->>'state','unavailable','Suppression makes an existing card non-actionable');
select is(private.cocreate_recruitment_projection(current_setting('cc.card')::uuid)->>'occupied',null::text,'Suppressed private destination exposes no current count');
select throws_ok($$select public.join_cocreate_recruitment('cc050000-0000-4000-8000-000000000011',gen_random_uuid(),current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,current_setting('cc.card')::uuid)$$,'42501',null,'Stale source cannot admit to suppressed group');
update private.cocreate_rooms set suppressed=false where id=current_setting('cc.room')::uuid;
update private.cocreate_recruitments set created_at=clock_timestamp()-interval '8 days',expires_at=clock_timestamp()-interval '1 day' where id=current_setting('cc.card')::uuid;
select is(private.cocreate_recruitment_projection(current_setting('cc.card')::uuid)->>'state','expired','Expiry is a live query state');
select throws_ok($$select public.join_cocreate_recruitment('cc050000-0000-4000-8000-000000000011',gen_random_uuid(),current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,current_setting('cc.card')::uuid)$$,'PT409',null,'Expired card is rejected inside admission transaction');
select set_config('request.jwt.claim.sub','cc050000-0000-4000-8000-000000000010',true);
update private.cocreate_settings set enabled=false;
select lives_ok($$select public.mutate_cocreate_recruitment('cc050000-0000-4000-8000-000000000010',gen_random_uuid(),current_setting('cc.hub')::uuid,current_setting('cc.room')::uuid,'retract',null,current_setting('cc.card')::uuid)$$,'Creator can retract exact own recruitment with gate OFF');
select throws_ok($$select public.get_cocreate_room_page_v2('cc050000-0000-4000-8000-000000000010',(current_setting('cc.ha')::jsonb->>'room_id')::uuid,(current_setting('cc.ha')::jsonb->>'episode_id')::uuid)$$,'42501',null,'Gate OFF still denies transcript');
select * from finish();
rollback;
